import glob, json, os, re
from collections import Counter
import claude_sessions as cs, codex_sessions as xs
IDRE = re.compile(r"\[(D\d+|M\d+)\]")

def tally(notices):
    seen = set(); dup = 0; dupch = 0
    for t in notices:
        ids = IDRE.findall(t)
        if ids and all(i in seen for i in ids):
            dup += 1; dupch += len(t)
        seen.update(ids)
    return len(notices), sum(len(t) for t in notices), dup, dupch

def main():
    for agent in ("claude", "codex"):
        tot = Counter(); n = 0
        for rep in (1, 2, 3):
