/** Every event of every initiative log at `commit`, ULID-ordered. */
export function eventsAt(repo: string, commit: string): Ev[] {
  const key = `${repo}@${commit}`
  const hit = evCache.get(key)
  if (hit !== undefined) return hit
  const files = git(repo, ['ls-tree', '-r', '--name-only', commit, '.sofar/initiatives']).split('\n').filter((f) => f.endsWith('events.jsonl'))
  const out: Ev[] = []
  for (const f of files) {
