 * stale stored values are used 0.92–1.00 of the time unless the conflict is
 * resolved before the reader sees it (the Memory Trust Gap). decisions.md and
 * the shards stay the human record, unchanged, and `sofar show <D> --history`
 * prints the entry whole.
 *
 * Two retirements keep their words. A re-log (r4-fixes U5) carries the same
 * words as the entry in force, so it is no old value. And a decision replaced
 * by one that narrowed its `path:` scope (a different scope, or an exemption
 * such as `!src/legacy/**`) still governs the paths left outside it — the
 * scoped older version a legacy path keeps (R4-RESEARCH §2.1).
 *
 * SOFAR_RETIRE=off renders every surface as before.
 */

/** A guard's `path:` scope as one canonical string, or null for none. */
function pathScope(guard: string | undefined): string | null {
  if (guard === undefined) return null
  const compiled = parseGuard(guard)
  if (compiled === null || compiled.domain !== 'path') return null
  return compiled.patterns
    .map((p) => `${p.negated ? '!' : ''}${p.source}`)
    .sort(byCodeUnit)
    .join(',')
}

/** True when a superseded decision's replacer declared a `path:` scope its own differs from: it still governs outside it. */
export function replacedWithinScope(state: InitiativeState, ordinal: number): boolean {
  const d = state.decisions[ordinal - 1]
  const by = d?.superseded_by
  if (d === undefined || by === undefined) return false
  const scope = pathScope(state.decisions[by - 1]?.guard)
  return scope !== null && pathScope(d.guard) !== scope
}

/** The live end of a replacement chain, when one is in force. */
function inForceHead(state: InitiativeState, ordinal: number, retired: ReadonlySet<number>): number | undefined {
  let head = ordinal
  const seen = new Set<number>()
  while (state.decisions[head - 1]?.superseded_by !== undefined && !seen.has(head)) {
    seen.add(head)
    head = state.decisions[head - 1]!.superseded_by!
  }
  return retired.has(head) ? undefined : head
}

/**
 * The tombstone each retired decision renders as on the agent surfaces, by
 * ordinal: `D5·xxxx — retired by D9·yyyy[; in force now: D12·zzzz] (history:
 * sofar show D5·xxxx --history[ --initiative <slug>])`, or `— retired: <task>
 * resolved` for one an `until` retired. Empty under SOFAR_RETIRE=off. A re-log
 * and a decision replaced within a narrower scope are left out: their words
 * are not an old value (see above). `initiative` is added to the history
 * command when the caller read another record than the bound one.
 */
export function tombstones(
  state: InitiativeState,
  options: { initiative?: string; env?: NodeJS.ProcessEnv } = {},
): Map<number, string> {
  const out = new Map<number, string>()
  if (!retireEnabled(options.env)) return out
  const retired = retiredOrdinals(state)
  const { absorbed } = relogAliases(state.decisions)
  const H = (n: number): string => handleAt(state.decisions, n)
  const where = options.initiative !== undefined ? ` --initiative ${options.initiative}` : ''
  for (const ordinal of [...retired].sort((a, b) => a - b)) {
    if (absorbed.has(ordinal) || replacedWithinScope(state, ordinal)) continue
    const d = state.decisions[ordinal - 1]!
    const history = ` (history: sofar show ${H(ordinal)} --history${where})`
    if (d.superseded_by !== undefined) {
      const head = inForceHead(state, ordinal, retired)
      const now = head !== undefined && head !== d.superseded_by ? `; in force now: ${H(head)}` : ''
      out.set(ordinal, `${H(ordinal)} — retired by ${H(d.superseded_by)}${now}${history}`)
    } else {
      out.set(ordinal, `${H(ordinal)} — retired: ${d.until} resolved${history}`)
    }
  }
  return out
}

/**
 * The full get_state view (r4-fixes A5): the folded state with every
 * tombstoned decision reduced to its id, date, its replacement or `until`,
 * and the tombstone line — no chose, over, because, rule or quote. The rest
 * of the state is the fold's own.
 */
export type CurrentOnlyDecision = DecisionState | { id: string; ts: string; retired: string; superseded_by?: number; until?: string }

export function currentOnlyState(state: InitiativeState, options: { initiative?: string; env?: NodeJS.ProcessEnv } = {}): Omit<InitiativeState, 'decisions'> & { decisions: CurrentOnlyDecision[] } {
  const stones = tombstones(state, options)
  if (stones.size === 0) return state
  return {
    ...state,
    decisions: state.decisions.map((d, i): CurrentOnlyDecision => {
      const line = stones.get(i + 1)
      if (line === undefined) return d
      return {
        id: d.id,
        ts: d.ts,
        ...(d.superseded_by !== undefined ? { superseded_by: d.superseded_by } : {}),
        ...(d.superseded_by === undefined && d.until !== undefined ? { until: d.until } : {}),
        retired: line,
      }
    }),
  }
}
