/** Map every bind re-log (same words as its target, only the check differs) to a check_bound on the chain's root. */
function mapRelogs(lines) {
  const evs = byId(lines).map((l) => JSON.parse(l))
  const decs = new Map() // id -> payload
  const root = new Map() // re-log id -> root decision id
  const relogIds = new Set()
  for (const e of evs) {
    if (e.type !== 'decision_logged') continue
    const p = e.payload
    const t = p.supersedes_id !== undefined ? decs.get(p.supersedes_id) : undefined
    if (t !== undefined && p.check !== undefined && sameDecisionText({ id: e.id, ...p }, { id: p.supersedes_id, ...t })) {
      relogIds.add(e.id)
      root.set(e.id, root.get(p.supersedes_id) ?? p.supersedes_id)
    }
    decs.set(e.id, p)
  }
  const rootOf = (id) => root.get(id) ?? id
  const out = []
  const ordinal = new Map()
  for (const e of evs) {
    if (e.type === 'decision_logged' && relogIds.has(e.id)) {
      const r = rootOf(e.id)
      out.push(JSON.stringify({ ...e, type: 'check_bound', payload: { decision: `D${ordinal.get(r)}`, decision_id: r, check: e.payload.check } }))
      continue
    }
    if (e.type === 'decision_logged') {
      const p = { ...e.payload }
      if (p.supersedes_id !== undefined && root.has(p.supersedes_id)) { p.supersedes_id = rootOf(p.supersedes_id); p.supersedes = `D${ordinal.get(p.supersedes_id)}` }
      if (Array.isArray(p.link_candidates)) p.link_candidates = [...new Set(p.link_candidates.map(rootOf))]
      if (p.supersedes_held !== undefined && Array.isArray(p.link_candidates)) p.supersedes_held = `D${ordinal.get(p.link_candidates[0])}`
      ordinal.set(e.id, ordinal.size + 1)
      out.push(JSON.stringify({ ...e, payload: p }))
      continue
    }
    if (e.type === 'decision_linked') {
      const p = { ...e.payload, decision_id: rootOf(e.payload.decision_id) }
      if (p.supersedes_id !== undefined) { p.supersedes_id = rootOf(p.supersedes_id); p.supersedes = `D${ordinal.get(p.supersedes_id)}` }
      p.decision = `D${ordinal.get(p.decision_id)}`
      out.push(JSON.stringify({ ...e, payload: p }))
      continue
    }
    out.push(JSON.stringify(e))
  }
  return { lines: out, relogs: relogIds.size, root }
}

/** Times a bind moved its rule's handle: the live head's ordinal before and after each bind event. */
function renumberings(lines, isBind) {
  const evs = byId(lines)
  let moved = 0
  for (let i = 0; i < evs.length; i++) {
    const e = JSON.parse(evs[i])
    if (!isBind(e)) continue
    const before = foldLines(evs.slice(0, i), '').state
    const after = foldLines(evs.slice(0, i + 1), '').state
    const targetId = e.type === 'check_bound' ? e.payload.decision_id : e.payload.supersedes_id
