    if (head(before) !== head(after)) moved++
  }
  return moved
}
const inForce = (st) => st.decisions.filter((d) => d.rule !== undefined && d.superseded_by === undefined).map((d) => `${d.rule}\u0000${d.check?.cmd ?? ''}`).sort()

let tot = { decisions: 0, relogs: 0, movedBefore: 0, movedAfter: 0 }
for (const r of [1, 2, 3]) {
  const base = `${CELLS}/round-4-sofar-r${r}/sofar/r${r}`
