Cursor (S18-20) session in the sofar arm, what would worktree adoption have pinned?
The A3 rule (mcp/start-session.ts adoptWorktreeSession), applied to the facts the
cell left behind:
  pointer   = the newest hook-seen session in the session's worktree at that moment:
              its own id when its SessionStart hook ran first (Codex: the sofar block is in
              the rollout before the call; Cursor headless fires sessionStart), else the
              previous hook session there;
  live      = other sessions with record events in that worktree at or after the
              pointer's start whose newest event (up to the call) is not a write-back/close;
  adopt iff pointer is a hook session, it had not finished before this server started,
              and live is empty. Right iff the adopted id is the session's own."""
import glob, json, os
from datetime import datetime
ROOT = '/Users/Shared/bench-cells/boopada'
CP = os.path.expanduser('~/.bench/cursor-home/.cursor/projects')
def ms(ts): return datetime.fromisoformat(ts.replace('Z', '+00:00')).timestamp() * 1000
def jl(path):
    for line in open(path, errors='replace'):
        try: yield json.loads(line)
        except Exception: pass
def stdout_id(path, key):
    for e in jl(path):
        if key in e: return e[key]
    return None
def record_events(wt):
    out = []
    for p in glob.glob(os.path.join(wt, '.sofar', 'initiatives', '*', 'events.jsonl')):
        for e in jl(p):
            if 'ts' not in e: continue
            pl = e.get('payload') or {}
            sub = pl.get('session_id') if e.get('type') == 'session_ended' and pl.get('session_id') else e.get('session')
            out.append((ms(e['ts']), sub, e.get('type'), e.get('source')))
    return sorted(out)
rows = []
for rep in (1, 2, 3):
    cell = f'{ROOT}/round-4-sofar-r{rep}/sofar/r{rep}'
    led = list(json.load(open(f'{ROOT}/round-4-sofar-r{rep}/ledger.json'))['cells'].values())[0]['sessions']
    wts = [cell + '/repo'] + sorted(glob.glob(cell + '/wt-*'))
    evs = {wt: record_events(wt) for wt in wts}
    order = sorted(((ms(v['launchedAt']), k) for k, v in led.items() if v.get('launchedAt')))
    for n in (9, 10, 11, 18, 19, 20, 25, 26, 27):
        S = f'S{n}'; host = 'cursor' if n in (18, 19, 20) else 'codex'
        start = ms(led[S]['launchedAt']); end = ms(led[S]['launchEndedAt'])
        if host == 'codex':
            own = stdout_id(f'{cell}/artifacts/{S}/agent.stdout', 'thread_id')
            roll = glob.glob(f'{cell}/codex-home/sessions/**/*{own}*.jsonl', recursive=True)
            entries = list(jl(roll[0])) if roll else []
            meta = next((e for e in entries if e.get('type') == 'session_meta'), {})
            cwd = (meta.get('payload') or {}).get('cwd', cell + '/repo')
            first = next((e for e in entries if e.get('type') == 'response_item' and (e.get('payload') or {}).get('type') == 'function_call' and str((e.get('payload') or {}).get('name', '')).startswith('sofar_')), None)
            T = ms(first['timestamp']) if first else None
            first_name = (first or {}).get('payload', {}).get('name')
            hooked = any('# Sofar status' in json.dumps(e) for e in entries if first is None or e.get('timestamp', '') < first['timestamp'])
        else:
            own = stdout_id(f'{cell}/artifacts/{S}/agent.stdout', 'session_id')
            fs = glob.glob(os.path.join(CP, '*', 'agent-transcripts', str(own), '*.jsonl'))
            first_name = None
            for f in sorted(fs)[:1]:
                for e in jl(f):
                    for x in (e.get('message') or {}).get('content') or []:
                        if isinstance(x, dict) and x.get('type') == 'tool_use' and first_name is None:
                            inp = x.get('input') or {}
                            if x.get('name') == 'CallDynamicTool' and str(inp.get('toolName', '')).startswith('sofar_'): first_name = inp.get('toolName')
            T = end  # no timestamps in Cursor transcripts: the whole window, the conservative bound
            cwd = None
            hooked = None
        wt = next((w for w in sorted(wts, key=len, reverse=True) if cwd and cwd.startswith(w)), None)
        if wt is None:  # Cursor: the worktree holding the session's own events
            wt = next((w for w in wts if any(s == own for _, s, _, _ in evs[w])), cell + '/repo')
        own_hook = any(s == own and src == 'hook' for _, s, _, src in evs[wt])
        if hooked is None: hooked = own_hook
        if first_name is None:
            rows.append((rep, S, host, 'no MCP call', '', '')); continue
        # the pointer: own id if SessionStart ran first, else the previous hook session in this worktree
        if hooked:
            pointer, p_ts = own, start
        else:
            prev = [(t, s) for t, s, ty, src in evs[wt] if src == 'hook' and t < T and s != own]
            pointer, p_ts = (prev[-1][1], min(t for t, s, *_ in evs[wt] if s == prev[-1][1])) if prev else (None, None)
        tails = {}
        for t, s, ty, src in evs[wt]:
            if p_ts is None or t < p_ts or t > T or not s or s == 'cli' or str(s).startswith('cli-'): continue
            tails[s] = (t, ty)
        fin = lambda ty: ty in ('session_ended', 'session_closed')
        own_tail = tails.get(pointer)
        others_live = [s for s, (t, ty) in tails.items() if s != pointer and not fin(ty)]
        if pointer is None: verdict = 'ask (no pointer)'
        elif own_tail and fin(own_tail[1]) and own_tail[0] < start: verdict = 'ask (pointer finished)'
        elif others_live: verdict = f'ask ({len(others_live)} other live)'
        else: verdict = 'adopt-RIGHT' if pointer == own else 'adopt-WRONG'
        rows.append((rep, S, host, first_name, os.path.basename(wt), verdict))
for r in rows: print(*r)
adopted = [r for r in rows if r[5].startswith('adopt')]
right = [r for r in adopted if r[5] == 'adopt-RIGHT']
print(f'sessions {len(rows)}; exactly one live (adopted) {len(adopted)}; right {len(right)} ({len(right)/max(1,len(adopted)):.0%})')
EOF
