function cappedEntries(
  display: string,
  raw: string,
  kind: 'D' | 'M',
  ids: ReadonlyArray<{ id: string }>,
  told: ReadonlySet<string>,
): string {
  const lines = raw.replace(/\\n$/, '').split('\\n')
  const entry = kind === 'D' ? /^- D([1-9][0-9]*)·/ : /^- M([1-9][0-9]*) /
