    const m = entry.exec(line)
    return m === null ? [] : [{ line, ordinal: Number(m[1]) }]
  })
  let held = 0
  let replaced = 0
  const open = entries.filter(({ line, ordinal }) => {
    if (line.includes(' — superseded by ')) {
      replaced += 1
      return false
