      const session = headField(line, 'session')
      if (session === null || !want.has(session) || live.has(session)) continue
      const ts = headField(line, 'ts')
      if (ts !== null && Date.parse(ts) >= sinceMs) live.add(session)
    }
    return live
  } catch {
