import re
SENT = re.compile(r'(?<=[.!?])\s+|\n+|;\s+')
def sentences(t):
    return [s for s in SENT.split(t) if s]
def surviving(slug, text, slugs, pat):
    """Sentences where the mention of slug survives F1-F3."""
    keep=[]
    for s in sentences(text):
        for m in pat.finditer(s):
            after=s[m.end():m.end()+8]; before=s[max(0,m.start()-20):m.start()].lower()
            if re.match(r" [DM]\d+\b", after): continue                 # F1 rationale cite
            if re.search(r"re-?homed (from|out of|into)\s*$", before): continue  # F2 re-home
            others={o for o in slugs if o!=slug and len(o)>3 and re.search(r'(?<![\w-])'+re.escape(o)+r'(?![\w-])', s)}
            if len(others)>=3: continue                                   # F3 sweep
            keep.append(s); break
    return keep
