/**
 * `switch` for a branch the harness abandons (segments `drop`, r4-fixes 4.2): bound on the branch itself, as a
 * teammate's `sofar switch` on a spike is, so the binding goes when the branch does and trunk's bindings never name
 * it. prebindWorktrees binds on main only to keep merged branches conflict-free, and an abandoned branch never
 * merges. Whatever else the switch wrote is discarded, as prebindWorktrees discards its scratch checkout. Idempotent.
 */
export async function bindInWorktree(dir: string, branch: string, sofarBin: string, binding: WorktreeBinding, env: Record<string, string>, label: string): Promise<string | null> {
  if (binding === "none") return null
  const file = join(dir, ".sofar", "bindings.json")
  const bindings = existsSync(file) ? (JSON.parse(readFileSync(file, "utf8")) as Record<string, string>) : {}
  const slug = bindings.main
  if (!slug) return null
  if (bindings[branch] === slug) return slug
  const r = await run([sofarBin, "switch", slug], { cwd: dir, env, timeoutMs: 120_000 })
  if (r.code !== 0) throw new Error(`sofar switch ${slug} on ${branch} failed: ${r.stderr || r.stdout}`)
  await gitOk(dir, "add", ".sofar/bindings.json")
  await gitOk(dir, "commit", "-q", "--no-verify", "-m", `bench: bind ${branch} to ${slug} before ${label}`)
  await gitOk(dir, "checkout", "-q", "--", ".sofar")
  await gitOk(dir, "clean", "-qfd", "--", ".sofar")
  return slug
}
