const groupDir = (group: string) => join(ROTATION, safe(group))
const membersDir = (group: string) => join(groupDir(group), "members")
const releasedFile = (window: string) => join(ROTATION, "released", safe(window))
/** This process's member file per group: one cell at a time. */
const mine = new Map<string, string>()
let exitHooked = false

function writeAtomic(file: string, tmp: string, body: string): void {
  writeFileSync(tmp, body)
  renameSync(tmp, file)
}

function readNumber(file: string): number {
  try {
    return Number(readFileSync(file, "utf8")) || 0
  } catch {
    return 0
  }
}

function stampRelease(window: string): void {
  mkdirSync(join(ROTATION, "released"), { recursive: true })
  writeAtomic(releasedFile(window), `${releasedFile(window)}.${process.pid}.tmp`, String(Date.now()))
