/** A group's members, live and gone; a dead runner's live record becomes a tombstone, seen gone now. */
function readMembers(group: string): MemberFile[] {
  const dir = membersDir(group)
  let names: string[] = []
  try {
    names = readdirSync(dir).filter((n) => !n.endsWith(".tmp"))
  } catch {
    return []
  }
  const out: MemberFile[] = []
  for (const name of names) {
    let m: MemberFile
    try {
      m = JSON.parse(readFileSync(join(dir, name), "utf8")) as MemberFile
    } catch {
      continue
    }
    if (m.goneAt === undefined && !alive(m.pid)) {
      m = { ...m, goneAt: Date.now() }
      writeAtomic(join(dir, name), join(dir, `${name}.${process.pid}.tmp`), JSON.stringify(m))
    }
    out.push(m)
  }
  return out
}

/**
 * Register this runner's cell as a member of its rotation group, before its setup, so its arm counts as live (and
 * owed its turns) from the start. Replaces this process's previous membership in the group. Every runner of a group
 * must rotate the same arms on the same lanes.
 */
export function joinRotation(spec: RotationSpec, arm: string, rep: number): void {
  const dir = membersDir(spec.group)
  mkdirSync(dir, { recursive: true })
  const clash = readMembers(spec.group).find((m) => m.goneAt === undefined && m.pid !== process.pid && (m.order.join(",") !== spec.order.join(",") || m.lanes !== spec.lanes))
  if (clash) throw new Error(`rotation group ${spec.group}: runner ${clash.pid} (${clash.arm}) rotates ${clash.order.join(",")} on ${clash.lanes} lane(s), this one ${spec.order.join(",")} on ${spec.lanes}; every runner of a round gives the same --arm-order and --claude-lanes`)
  leaveRotation(spec.group)
  const file = join(dir, `${process.pid}-${safe(arm)}-r${rep}`)
  const m: MemberFile = { pid: process.pid, arm, rep, order: spec.order, lanes: spec.lanes, graceMs: spec.graceMs, pos: null, granted: [], joinedAt: Date.now() }
  writeAtomic(file, `${file}.tmp`, JSON.stringify(m))
  mine.set(spec.group, file)
  if (!exitHooked) {
    exitHooked = true
    process.on("exit", () => leaveRotation())
  }
}

/** Leave a group (or every group): the member file stays as a tombstone, with when it left. */
export function leaveRotation(group?: string): void {
  for (const [g, file] of [...mine]) {
    if (group !== undefined && g !== group) continue
    try {
      const m = JSON.parse(readFileSync(file, "utf8")) as MemberFile
      writeAtomic(file, `${file}.tmp`, JSON.stringify({ ...m, goneAt: Date.now() }))
    } catch {
      // the locks dir was cleared
    }
    mine.delete(g)
  }
}

function ownMember(turn: WindowTurn): { file: string; m: MemberFile } {
  let file = mine.get(turn.group)
  let m: MemberFile | undefined
  try {
    m = file ? (JSON.parse(readFileSync(file, "utf8")) as MemberFile) : undefined
  } catch {
    m = undefined
  }
  if (!file || !m || m.arm !== turn.arm || m.rep !== turn.rep || m.goneAt !== undefined) {
    joinRotation(turn, turn.arm, turn.rep)
    file = mine.get(turn.group) as string
    m = JSON.parse(readFileSync(file, "utf8")) as MemberFile
  }
  return { file, m }
}

function noteAsk(turn: WindowTurn): void {
  const { file, m } = ownMember(turn)
  const at: [number, number] = [turn.rep, turn.index]
  if (!m.pos || m.pos[0] < at[0] || (m.pos[0] === at[0] && m.pos[1] < at[1])) writeAtomic(file, `${file}.tmp`, JSON.stringify({ ...m, pos: at }))
