function takeTurn(window: string, lane: number, ticket: string, turn: WindowTurn, pick: (GroupPick & { grant: RotTicket }) | undefined): WindowGrant {
  const now = Date.now()
  const grant: WindowGrant = {
    at: new Date(now).toISOString(),
    window,
    lane,
    group: turn.group,
    rep: turn.rep,
    index: turn.index,
    arm: turn.arm,
    turn: pick ? pick.turn : null,
    order: pick ? pick.order : laneOrder(turn.order, turn.index, turn.lanes, lane),
    by: pick ? pick.by : "arrival",
    skipped: pick ? pick.skipped : [],
    waitedMs: now - Number(ticket.split("-")[0]),
