interface Next {
  go: boolean
  rotated: boolean
  pick?: GroupPick & { grant: RotTicket }
  waitFor?: string
  until?: number
}

/** May `ticket` take `window` now: the oldest live ticket goes, unless the queue holds rotated tickets (lib/lanes.ts pickGroup). */
function nextOnWindow(window: string, lane: number, ticket: string): Next {
  const dir = join(QUEUES, safe(window))
  const names = windowQueue(window)
  const rot: RotTicket[] = []
  const plain: string[] = []
  for (const name of names) {
    let body = ""
    try {
      body = readFileSync(join(dir, name), "utf8")
