    const members: MemberView[] = readMembers(group).map((m) => ({ arm: m.arm, rep: m.rep, pos: m.pos, granted: m.granted, live: m.goneAt === undefined, joinedAt: m.joinedAt, goneAt: m.goneAt }))
    const pick = pickGroup({ lane, tickets: rot.filter((t) => t.group === group), members, lastRelease, now })
    if (pick && "grant" in pick) candidates.push({ name: pick.grant.name, pick })
    else if (pick) {
      waitFor = pick.waitFor
      until = pick.until
    }
  }
  const first = candidates.sort((a, b) => (a.name < b.name ? -1 : 1))[0]
  return { go: first?.name === ticket, rotated: true, pick: first?.pick, waitFor, until }
}
