export async function findOrphans(root: string, dirs: string[] = []): Promise<ProcInfo[]> {
  const table = await processTable()
  const byPid = new Map(table.map((p) => [p.pid, p]))
  const spared = new Set<number>()
  for (let pid = process.pid; pid > 1 && !spared.has(pid); pid = byPid.get(pid)?.ppid ?? 0) spared.add(pid)
  const groups = liveGroups()
  const mine = liveLaunches()
  const over = (launch: string): boolean => {
    if (launch.startsWith(`${OWNER}-`)) return !mine.has(launch)
    const [pid, sec] = launch.split("-").map(Number) as [number, number]
    const owner = byPid.get(pid)
    return !owner || Math.abs(owner.startedMs / 1000 - sec) > 3
  }
  const candidates = table.filter((p) => !spared.has(p.pid) && !groups.has(p.pgid))
  const marked = candidates.filter((p) => p.cell && p.launch && isUnder(resolved(p.cell), root) && over(p.launch))
  const adopted = dirs.length ? candidates.filter((p) => p.ppid === 1 && !p.launch) : []
  const cwd = await cwds(adopted.map((p) => p.pid))
  return [...marked, ...adopted.filter((p) => dirs.some((d) => isUnder(cwd.get(p.pid), d)))]
}

/** Stop every orphan findOrphans names (TERM, then KILL after the grace); returns what was stopped. */
export async function sweepOrphans(root: string, dirs: string[] = []): Promise<string[]> {
  const found = await findOrphans(root, dirs)
  if (found.length) await stop([], found)
  return found.map(procLine)
}

/** After a session: what run() stopped when its launch ended, then the sweep of its checkout. */
export async function sweepSession(root: string, checkout: string): Promise<string[]> {
  const swept = await sweepOrphans(root, [checkout])
  return [...takeReaped(checkout), ...swept]
}

